/// Look up a reachable CREATURE spawn descriptor by dense `minecraft:entity_type` id.
pub fn creature_spawn_descriptor_by_id(id: u16) -> Option<&'static EntitySpawnDescriptor> {
    let idx = CREATURE_ENTITY_SPAWN_DESCRIPTORS
        .binary_search_by_key(&id, |d| d.id)
        .ok()?;
    Some(&CREATURE_ENTITY_SPAWN_DESCRIPTORS[idx])
}

/// Look up a reachable CREATURE spawn descriptor by namespaced entity id.
pub fn creature_spawn_descriptor_by_name(name: &str) -> Option<&'static EntitySpawnDescriptor> {
    CREATURE_ENTITY_SPAWN_DESCRIPTORS
        .iter()
        .find(|d| d.name == name)
}
